};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_ISU_CD_onclick
 * @description img_ISU_CD 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_ISU_CD_onclick = async function() {
    try {
        let vListMthTpCd = cmb_LIST_METHD_TP_CD.getValue();
        if (cmb_LIST_METHD_TP_CD.getValue() === "") {
            await $c.win.alert("먼저 [상장방식]을 선택하세요.");
            cmb_LIST_METHD_TP_CD.focus();
            return;
        }
        scwin.fn_GetPar = scwin.getParIsuCd;
        scwin.fn_SetPar = scwin.setParIsuCd;
        if (vListMthTpCd === LIST_METHD_TP_CD_1) {
            // 신주상장
            $c.lc.fn_PopFindNewIsuOfIsur();
        } else if (vListMthTpCd === LIST_METHD_TP_CD_2 || vListMthTpCd === LIST_METHD_TP_CD_3) {
            // 추가(LIST_METHD_TP_CD_2),변경상장(LIST_METHD_TP_CD_3)
            $c.lc.fn_PopFindIsuOfIsur();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92002.img_ISU_CD_onclick" });
    }
};

