/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    try {
        let vCurDate = $c.ut.cGetToday("yyyymmdd");
        if (scwin.vBzProcsNo === "") {
            buttonSet.setInsertStatus();
            scwin.initForm('C');
        } else {
            scwin.initForm('X');
            if (vCurDate <= edt_LIST_DD.getValue()) {
                buttonSet.setUpdateStatus();
            } else {
                if (dts_Isu.getCellData(1, "DISCLS_YN") === 'Y') {
                    buttonSet.setErrorStatus(); // disable 시킨다.

                } else {
                    buttonSet.setUpdateStatus();
                }
            }
        }
        if (scwin.gAcptNo !== "" && scwin.vBzProcsNo === "") {
            btn_RecvIsuDel.setBackgroundImage("../img/btn_RcvdocDel.gif");
            btn_RecvIsuDel.setDisabled(false);
        } else {
            btn_RecvIsuDel.setBackgroundImage("../img/btn_RcvdocDel_d.gif");
            btn_RecvIsuDel.setDisabled(true);
        }
        scwin.setTabPanel();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92002.dts_Isu_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_IsuDtl_OnLoadCompleted
 * @description dts_IsuDtl 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_IsuDtl_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.gAcptNo !== "" && scwin.vBzProcsNo === "") {
            let vListMthTpCd = dts_Isu.getCellData(1, "LIST_METHD_TP_CD");
            if (vListMthTpCd === LIST_METHD_TP_CD_1 || vListMthTpCd === LIST_METHD_TP_CD_2) {
                // 주식발행사유로 체크하지말고 건수로 하자..
                if (dts_IsuDtl.getRowCount() === 0) {
                    dts_IsuDtl.insertRow();
                    dts_IsuDtl.setCellData(1, "ISU_RND", dts_Isu.getCellData(1, "ISU_RND"));
                    dts_IsuDtl.setCellData(1, "ISU_PRC", dts_Isu.getCellData(1, "ISU_PRC"));
                    dts_IsuDtl.setCellData(1, "ISU_SHRS", dts_Isu.getCellData(1, "ISU_SHRS"));
                    dts_IsuDtl.setCellData(1, "ISU_DD", dts_Isu.getCellData(1, "ISU_DD"));
                    dts_IsuDtl.setCellData(1, "PER1STK_CAP", dts_Isu.getCellData(1, "PER1STK_CAP"));
                } else {
                    dts_IsuDtl.setBroadcast(false);
                    for (j = 1; j <= dts_IsuDtl.getRowCount(); j++) {
                        dts_IsuDtl.setCellData(j, "ISU_RND", dts_Isu.getCellData(1, "ISU_RND"));
                    }
                    dts_IsuDtl.setBroadcast(true, true);
                }

                /*
                var vRsnCd = getObjectValue(cmb_STK_ISU_RSN_CD);
                var gDtl = 'Y';
                alert('[vRsnCd]'+vRsnCd);
                if (vRsnCd == '612' ||
                	vRsnCd == '613' ||
                	vRsnCd == '614' ||
                	vRsnCd == '617' ||
                	vRsnCd == '618' ||
                	vRsnCd == '619' ||
                	vRsnCd == '620' ||
                	vRsnCd == '621' ||
                	vRsnCd == '622' ||
                	vRsnCd == '623' ||
                	vRsnCd == '624'  ) {
                	gDtl = 'N';
                }
                 */
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92002.dts_IsuDtl_OnLoadCompleted" });
    }
};

