/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        // var dtsPrtdepo = dts_PRTDEPO.ExportData(1, dts_PRTDEPO.CountRow, true);

        // alert("fn_parentRefresh dts_PRTDEPO.ClearAll start=" + dtsPrtdepo);

        scwin.parentRefresh(); // 목록 다시 조회

        if (scwin.TR_JOB === 'D') {
            $c.lc.fn_alertMsg('S');
            await $c.win.closePopup();
        } else {
            await scwin.readSync();
            buttonSet.setUpdateStatus();

            // alert("fn_parentRefresh dts_PRTDEPO.ClearAll end");

            // dts_PRTDEPO.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=STKCERT_ISU_PRTDEPO_INOUT";
            // dts_PRTDEPO.ImportData(dtsPrtdepo);
            // dts_PRTDEPO.reset();

            // alert("fn_parentRefresh dts_PRTDEPO.reset end");

            let msg = "성공적으로 처리되었습니다. \n" + " \n" + " \n" + "시장안내문작성 화면으로 이동하시겠습니까?";
