};

/**
 * @method
 * @name cmb_STK_ISU_RSN_CD_onselchange
 * @description cmb_STK_ISU_RSN_CD onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_STK_ISU_RSN_CD_onselchange = async function() {
    try {
        if (!btn_RecvIsuDel.getDisabled()) {
            if (js_market === '1' && scwin.vPageTYp === "2" && cmb_LIST_METHD_TP_CD.getValue() === LIST_METHD_TP_CD_3) {
                // 유가, 변경상장
                if (cmb_STK_ISU_RSN_CD.getValue() !== "" &&
                    cmb_STK_ISU_RSN_CD.getValue() !== "170" &&
                    cmb_STK_ISU_RSN_CD.getValue() !== "171" &&
                    cmb_STK_ISU_RSN_CD.getValue() !== "172" &&
                    cmb_STK_ISU_RSN_CD.getValue() !== "173" &&
                    cmb_STK_ISU_RSN_CD.getValue() !== "174" &&
                    cmb_STK_ISU_RSN_CD.getValue() !== "177" &&
                    cmb_STK_ISU_RSN_CD.getValue() !== "118" &&
                    cmb_STK_ISU_RSN_CD.getValue() !== "160" &&
                    cmb_STK_ISU_RSN_CD.getValue() !== "161" &&
                    cmb_STK_ISU_RSN_CD.getValue() !== "180" &&
                    cmb_STK_ISU_RSN_CD.getValue() !== "162" &&
                    cmb_STK_ISU_RSN_CD.getValue() !== "163" &&
                    cmb_STK_ISU_RSN_CD.getValue() !== "175" &&
                    cmb_STK_ISU_RSN_CD.getValue() !== "176") {
                    if (!confirm("변경상장에서 안내문 형식이 정의되지 않은 주식 발행사유 입니다. \n그래도 선택한 주식발행사유를 입력하시겠습니까?")) {
                        cmb_STK_ISU_RSN_CD.setValue('');
                        return;
                    }
                }
            }
        }
        scwin.setTabPanel(); // 625:우선주의 보통주전환  추가(2017.07.14)

        await scwin.calcuAccIsuShrs();
        await scwin.calcuAccIsuCap();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92002.cmb_STK_ISU_RSN_CD_onselchange" });
    }
};

