/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} trsIdx trsIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(trsIdx) {
    // dts_Isu.NameValue(1, "JOB_TYPE") = jobType;
    // alert('[JOB_TYPE]'+dts_Isu.NameValue(1, "JOB_TYPE") );

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

    dts_Isu.setCellData(1, "ISUR_CD", txb_ISUR_CD.getValue());
    dts_Isu.setCellData(1, "LIST_BZ_TP_CD", scwin.getListBzTpCd());
    dts_Isu.setCellData(1, "PREFSTK_TP_CD", scwin.getCheckboxNprefStk(chk_PREFSTK_TP_CD, cmb_STKCERT_KIND_CD.getValue()));
    dts_Isu.setCellData(1, "INDEFINPD_YN", scwin.getCheckboxData(chk_INDEFINPD_YN));
    dts_Isu.setCellData(1, "PARTCTP_YN", scwin.getCheckboxData(chk_PARTCTP_YN));
    dts_Isu.setCellData(1, "ACCTP_YN", scwin.getCheckboxData(chk_ACCTP_YN));
    dts_Isu.setCellData(1, "NDIVTM_VOTERGHT_YN", scwin.getCheckboxData(chk_NDIVTM_VOTERGHT_YN));
    dts_Isu.setCellData(1, "NEWSTK_REL_LAWST_YN", scwin.getCheckboxData(chk_NEWSTK_REL_LAWST_YN)); /*ORG SRC: dts_Isu.NameString(1, "BACKLIST_YN") = (fn_getCheckboxData(chk_BACKLIST_YN) == "Y" ? "Y" : '');*/ X = (scwin.getCheckboxData(chk_BACKLIST_YN) === "Y" ? "Y" : ''); /*ORG SRC: dts_Isu.NameString(1, "NPARVALSTK_YN") = (fn_getCheckboxData(chk_NPARVALSTK_YN) == "Y" ? "Y" : '');*/ X = (scwin.getCheckboxData(chk_NPARVALSTK_YN) === "Y" ? "Y" : '');
    const sbmOptions = {
        id : "sbm_dts_BackList",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_BackList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_BackList.insertRow();

    /*2010.03.05 우회상장 시 우회상장일도 같이 입력 */
    /*2010.07.16 우회상장 시 주식발행코드 입력 */
    if (chk_BACKLIST_YN.checked) {
        dts_BackList.setCellData(1, "ISUR_CD", dts_Isu.getCellData(1, "ISUR_CD"));
        dts_BackList.setCellData(1, "BZ_PROCS_NO", dts_Isu.getCellData(1, "BZ_PROCS_NO"));
        dts_BackList.setCellData(1, "BACKLIST_DD", dts_Isu.getCellData(1, "LIST_DD"));
        dts_BackList.setCellData(1, "BACKLIST_DESIGN_YN", "Y");
        dts_BackList.setCellData(1, "STK_ISU_RSN_CD", dts_Isu.getCellData(1, "STK_ISU_RSN_CD"));
    } else {
        if (dts_BackList.getRowCount() > 0) {
            dts_BackList.removeRow(1);
        }
    }

    // 20081017 코스닥이고 발행사유가 이익소각이면 발행일자는 ~ 셋팅된다.
    /* 모델변경으로 제외(not null -> null) 2009.03.31
		if (getObjectValue(cmb_STK_ISU_RSN_CD) == "626"){
			if (dts_Isu.NameString(1, "ISU_DD") == ""){
dts_Isu.setNameString(1, "ISU_DD","~") ;
			}
		}
     */

    dts_IsuDtl.setBroadcast(false);
    for (i = 1; i <= dts_IsuDtl.getRowCount(); i++) {
        dts_IsuDtl.setCellData(i, "BZ_PROCS_NO", dts_Isu.getCellData(1, "BZ_PROCS_NO"));
        dts_IsuDtl.setCellData(i, "SEQ", i);
        // dts_IsuDtl.NameValue(i, "JOB_TYPE") = TR_JOB_INSERT; //delete 후 insert 한다.

    }
    dts_IsuDtl.setBroadcast(true, true);
    dts_PRTDEPO.setBroadcast(false);
    for (i = 1; i <= dts_PRTDEPO.getRowCount(); i++) {
