/**
 * @method
 * @name print
 * @description print 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.print = async function() {
    const vReportCd = cmb_REPORT_CD.getValue(); // 1^인쇄,2^보호예수인쇄,3^통합인쇄
    let vBzProcsKey = scwin.vBzProcsNo;
    if (vReportCd === "1") {
        let isuRsnCd = cmb_STK_ISU_RSN_CD.getValue();
        if (isuRsnCd === '643') {
            // 상호변경(코)
            await scwin.print11(vBzProcsKey);
        } else {
            await scwin.print12(vBzProcsKey, 'N');
        }
    } else if (vReportCd === "2") {
        await scwin.print2(vBzProcsKey); // 우리기술...

    } else if (vReportCd === "3") {
        const sbmOptions = {
            id : "sbm_dts_Report_4",
            action : "/Listing.do",
            ref : "",
            target : "dts_Report_4=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        let pValue = "";
        let k = 0;
        for (let i = 1; i <= dts_Report_4.getRowCount(); i++) {
            if (k === 0) {
                pValue = dts_Report_4.getCellData(i, "BZ_PROCS_NO");
            } else {
                pValue = pValue + "," + dts_Report_4.getCellData(i, "BZ_PROCS_NO");
            }
            k++;
        }
        vBzProcsKey = pValue;
        await scwin.print12(vBzProcsKey, 'Y');
    }
};

