/**
 * @method
 * @name setObjectState
 * @description set Object State 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setObjectState = async function() {
    // alert('vSPOT_ISU_TRD_MKT_TP_CD]'+vSPOT_ISU_TRD_MKT_TP_CD);
    panel_Discls_Viewer.hide();
    if (js_market === '9') {
        panel_Discls_Viewer.show("");
    }
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === '1') {
        panel_KSE.show(""); // 심볼
        panel_STKCERT_MIX.show(""); // 혼용유통기간
        panel_Print.show(""); // 2014.12.3 인쇄 가능으로 요청
        panel_BACKLIST_YN.hide();
        panel_KOSDAQ.hide();
        panel_PAIDCAPINC_ISU_TP_CD.hide();
        $c.cm.setColumnProp(grd_IsuDtl, "CORPBND_ISU_RND", "Show", false);

        // 유가의 경우 상장 수수료에 관한 내용이 나오지 않는다.
        btn_send.hide();
        pan_listFee_cos.hide();
    } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === '2' || scwin.vSPOT_ISU_TRD_MKT_TP_CD === "6") {
        panel_KSE.hide();
        panel_STKCERT_MIX.hide(); // 혼용유통기간
        panel_Print.show("");
        panel_BACKLIST_YN.show("");
        panel_KOSDAQ.show("");
        panel_PAIDCAPINC_ISU_TP_CD.show("");
        $c.cm.setColumnProp(grd_IsuDtl, "CORPBND_ISU_RND", "Show", true);

        // 코스닥의 경우 접수번호가 없으면 상장수수료를 발송할 수 없다.
        if (scwin.gAcptNoListFee === "") {
            pan_listFee_cos.hide();
            btn_send.hide();
        } else {
            pan_listFee_cos.show("");
            btn_send.show("");
            await scwin.listFee();
        }
    }
    if (scwin.vSecugrpID === SECUGRP_ID_DR) {
        panel_PARVAL.hide();
        panel_ISU_CAP.hide();
        scwin.visuShrsLabelNm = "DR";
        lb_ISU_SHRS.setValue("증감" + scwin.visuShrsLabelNm + "수");
        lb_BF_ACC_ISU_SHRS.setValue("변경전 상장" + scwin.visuShrsLabelNm + "수");
        lb_ACC_ISU_SHRS.setValue("상장DR수");
        lb_INDVDL_INCDEC_LIST_SHRS.setValue("개별증감" + scwin.visuShrsLabelNm + "수");
        edt_PARVAL.MaxDecimalPlace = 3;
    } else {
        panel_PARVAL.show("");
        panel_ISU_CAP.show("");
        scwin.visuShrsLabelNm = "주식";
        edt_PARVAL.MaxDecimalPlace = 0;
    }
    if (scwin.vSecugrpID === SECUGRP_ID_FS) {
        edt_PARVAL.MaxDecimalPlace = 3;
    }
    if (scwin.vSecugrpID === SECUGRP_ID_DR || scwin.vSecugrpID === SECUGRP_ID_FS) {
        panel_CURR_ISO_CD.show("");
        txb_CURR_ISO_NM_1.show("");
        txb_CURR_ISO_NM_2.show("");
        txb_CURR_ISO_NM_3.show("");
        txb_CURR_ISO_NM_4.show("");
    } else {
        panel_CURR_ISO_CD.hide();
        txb_CURR_ISO_NM_1.hide();
        txb_CURR_ISO_NM_2.hide();
        txb_CURR_ISO_NM_3.hide();
        txb_CURR_ISO_NM_4.hide();
    }
};

