/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    let vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[회사코드] 항목값이  없습니다.");
        txb_ISUR_CD.focus();
        return false;
    }
    if (cmb_LIST_METHD_TP_CD.getValue() === "") {
        await $c.win.alert("[상장방식]을 선택하세요.");
        cmb_LIST_METHD_TP_CD.focus();
        return false;
    }
    let vListMthTpCd = cmb_LIST_METHD_TP_CD.getValue();
    if (scwin.vPageTYp === '1') {
        if (vListMthTpCd !== LIST_METHD_TP_CD_2) {
            // alert("이화면에서는  상장방식을 [신주상장, 추가상장]만 선택할 수 있습니다.");cmb_LIST_METHD_TP_CD.focus();return false;
            await $c.win.alert("이화면에서는  상장방식을 [추가상장]만 선택할 수 있습니다.");
            cmb_LIST_METHD_TP_CD.focus();
            return false;
        }
    } else if (scwin.vPageTYp === '2') {
        if (vListMthTpCd !== LIST_METHD_TP_CD_3) {
            await $c.win.alert("이화면에서는  상장방식을 [변경상장]만 선택할 수 있습니다.");
            cmb_LIST_METHD_TP_CD.focus();
            return false;
        }
    }
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return false;
    }
    if (cmb_LIST_METHD_TP_CD.getValue() === LIST_METHD_TP_CD_1) {
        let dbchkCnt = -1;
        dbchkCnt = await scwin.checkDoubleListed();
        if (dbchkCnt > 0) {
            await $c.win.alert("선택종목은 이미상장된 종목입니다. 확인후 다시 조치바랍니다.");
            return false;
        }
    }
    if (cmb_LIST_METHD_TP_CD.getValue() === LIST_METHD_TP_CD_1) {
        if (txb_ISU_SRT_CD.getValue() === "") {
            await $c.win.alert("[종목단축코드]항목값이  없습니다."); // txb_ISU_SRT_CD.focus();return false;

        }
        if (txb_ISU_KOR_NM.getValue() === "") {
            await $c.win.alert("[한글종목명]을 입력하세요.");
            txb_ISU_KOR_NM.focus();
            return false;
        }
        if (txb_ISU_KOR_ABBRV.getValue() === "") {
            await $c.win.alert("[한글종목약명]을 입력하세요.");
            txb_ISU_KOR_ABBRV.focus();
            return false;
        }
        if (txb_ISU_ENG_NM.getValue() === "") {
            await $c.win.alert("[영문종목명]을 입력하세요.");
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (txb_ISU_ENG_ABBRV.getValue() === "") {
            await $c.win.alert("[영문종목약명]을 입력하세요.");
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "1") {
            if (txb_ISU_ENG_SYMBL.getValue() === "") {
