/**
 * @method
 * @name checkIsuDtlDtl
 * @description check Isu Dtl Dtl 처리
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkIsuDtlDtl = async function(dtsObj) {
    if (dtsObj.getRowCount() === 0) {
        await $c.win.alert("주식발행상세정보를 입력하세요.");
        return false;
    }
    for (j = 1; j <= dtsObj.getRowCount(); j++) {
        if (dtsObj.getCellData(j, "ISU_RND") === "") {
            await $c.win.alert("주식발행상세정보에서 " + j + "행의 [개별발행회차]를 입력하세요.");
            return false;
        }
        if (dtsObj.getCellData(j, "ISU_DD") === "") {
            await $c.win.alert("주식발행상세정보에서 " + j + "행의 [개별발행일]를 입력하세요.");
            return false;
        }
        if (dtsObj.getCellData(j, "ISU_PRC") === "") {
            // alert("주식발행상세정보에서 "+ j+"행의 [개별발행가]를 입력하세요.");return false;

        }
        if (dtsObj.getCellData(j, "ISU_SHRS") === "") {
            await $c.win.alert("주식발행상세정보에서 " + j + "행의 [개별증감주식수]를 입력하세요.");
            return false;
        }
    }
    return true;
};

/**
 * @method
