 */
scwin.checkPRTDEPO = async function(dtsObj) {
    for (j = 1; j <= dtsObj.getRowCount(); j++) {
        if (dtsObj.getCellData(j, "NM") === "") {
            await $c.win.alert("의무보호목록에서 " + j + "행의 성명을 입력하세요.");
            return false;
        }
        if (dtsObj.getCellData(j, "RESDBZ_REG_NO") === "") {
            await $c.win.alert("의무보유목록에서 " + j + "행의 [생년월일(사업자번호)]를 입력하세요.");
            return false;
        }
        /*
        if (dtsObj.NameValue(j, "RSN_OCCR_DDTM") == "") {
        	alert("보호예수목록에서 "+ j+"행의 [사유발생일]을 입력하세요.");return false;
        }
         */
        if (dtsObj.getCellData(j, "PRTDEPO_PRN_TP_CD") === "") {
            await $c.win.alert("의무보유목록에서 " + j + "행의 [의무보유대상자구분]를 입력하세요.");
            return false;
        }
        if (dtsObj.getCellData(j, "PRTDEPO_SHRS") === "") {
            await $c.win.alert("의무보유목록에서 " + j + "행의 [의무보유주식수]를 입력하세요.");
            return false;
        }
        if (dtsObj.getCellData(j, "PRTDEPO_OBJ_KIND_CD") === "") {
            await $c.win.alert("의무보유목록에서 " + j + "행의 [의무보유대상종류]를 입력하세요.");
            return false;
        }
        if (dtsObj.getCellData(j, "PRTDEPO_RSN_CD") === "") {
            await $c.win.alert("의무보유목록에서 " + j + "행의 [의무보유사유]를 입력하세요.");
            return false;
        }
        /* 2009.04.14 변경
        if (dtsObj.NameValue(j, "PRTDEPO_STRT_DD") == "") {
        	alert("보호예수목록에서 "+ j+"행의 [보호예수시작일]을 입력하세요.");return false;
        }
        if (dtsObj.NameValue(j, "PRTDEPO_END_DD") == "") {
        	alert("보호예수목록에서 "+ j+"행의 [보호예수종료일]을 입력하세요.");return false;
        }
         */
    }
    return true;
};

