/**
 * @method
 * @name checkZeroNumber
 * @description 신주상장또는 추가상장시 0으로 입력했는지 체크
 * @param {Object} obj 컴포넌트
 * @param {String} str str
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkZeroNumber = async function(obj, str) {
    if (scwin.vSecugrpID === SECUGRP_ID_ST) {
        if (obj.getValue() === 0) {
            await $c.win.alert("[" + str + "]를 '" + obj.getValue() + "'으로 입력하셨습니다. 확인 후 재입력바랍니다.");
            obj.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name getListBzTpCd
 * @description get List Bz Tp Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.getListBzTpCd = function() {
    let str = "";
    if (cmb_LIST_METHD_TP_CD.getValue() === LIST_METHD_TP_CD_1) {
        str = LIST_BZ_TP_CD_120; // 신주상장

    } else if (cmb_LIST_METHD_TP_CD.getValue() === LIST_METHD_TP_CD_2) {
        str = LIST_BZ_TP_CD_130; // 추가상장

    } else if (cmb_LIST_METHD_TP_CD.getValue() === LIST_METHD_TP_CD_3) {
        str = LIST_BZ_TP_CD_141; // 변경상장

    }
    return str;
};

/**
 * @method
 * @name getCheckboxNprefStk
 * @description get Checkbox Npref Stk 처리
 * @param {Object} obj 컴포넌트
 * @param {*} stk_knd stk_knd
 * @returns {void}
 * @hidden N
 */
scwin.getCheckboxNprefStk = function(obj, stk_knd) {
    let val;
    if (obj.checked) {
        val = '2';
    } else {
        if (stk_knd === "000" || stk_knd === "KDR") {
            val = '0';
        } else {
            val = '1';
        }
    }
    return val;
};

