/**
 * @method
 * @name chkPrtdepoCond01
 * @description 상장방식-보호예수체크용코드있냐?
 * @returns {void}
 * @hidden N
 */
scwin.chkPrtdepoCond01 = function() {
    let vRsnCd = cmb_STK_ISU_RSN_CD.getValue();
    if (vRsnCd === '141' || // DR분할
        vRsnCd === '142' || // DR병합
        vRsnCd === '170' || // 액면병합
        vRsnCd === '171' || // 액면분할
        vRsnCd === '172' || // 감자(주식병합)
        vRsnCd === '173' || // 회사분할(존속)
        vRsnCd === '174') {
        // 감자(주식소각)
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name chkPrtdepoCond02
 * @description 보호예수건수가있냐?
 * @returns {void}
 * @hidden N
 */
scwin.chkPrtdepoCond02 = function() {
    // if (dts_PRTDEPO.CountRow == 0) {
    if (scwin.gPrtdepoCount === 0) {
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name chkPrtdepoCond03
 * @description 보호예수수정건수가있냐?
 * @returns {void}
 * @hidden N
 */
scwin.chkPrtdepoCond03 = function() {
    // var gPrtdepoCount = dts_PRTDEPO.CountRow;
    // alert("gPrtdepoCount="+gPrtdepoCount);
    let gStat;
    let gStatCnt = 0;
    for (let k = 1; k <= dts_PRTDEPO.getRowCount(); k++) {
        gStat = dts_PRTDEPO.getRowStatus(k);
        // if (gStat == TB_JOB_UPDATE) {
        if (gStat === TB_JOB_NORMAL) {
            gStatCnt++;
        }
    }

    // alert("gStatCnt="+gStatCnt);
    if (scwin.gPrtdepoCount === gStatCnt) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);

            /*
            alert(
            	"test vBzProcsNo="+vBzProcsNo+"\n"+
            	"fn_chkPrtdepoCond_00="+fn_chkPrtdepoCond_00()+"\n"+
            	"fn_chkPrtdepoCond_01="+fn_chkPrtdepoCond_01()+"\n"+
            	"fn_chkPrtdepoCond_02="+fn_chkPrtdepoCond_02()+"\n"+
            	"fn_chkPrtdepoCond_03="+fn_chkPrtdepoCond_03()+"\n"+

            	"fn_chkPrtdepoCond_02 count="+dts_PRTDEPO.CountRow

            );
             */

            if ((js_market === '1') &&
                scwin.chkPrtdepoCond00() && scwin.chkPrtdepoCond01()) {
                // alert("test vBzProcsNo="+fn_chkPrtdepoCond_00() + fn_chkPrtdepoCond_01());

                if (scwin.chkPrtdepoCond) {
                    await scwin.prtdepoReadSyncSTKCount();
                }
            }
            if ((js_market === '1') &&
                scwin.chkPrtdepoCond00() && scwin.chkPrtdepoCond01() && scwin.chkPrtdepoCond02() &&
                (scwin.gPrtdepoCount > 0) &&
                scwin.chkPrtdepoCond) {
                await $c.win.alert("               【의무보유 시장조치 안내】\n해당 종목에 의무보유중인 증권이 있습니다.\n의무보유내역에서 의무보유수량을 정정조치하여 주시기 바랍니다.");
                await scwin.prtdepoReadSyncSTK();
                scwin.chkPrtdepoCond = false;
                scwin.formCd = "68155";
                return;
            }
            if ((js_market === '1') &&
                scwin.chkPrtdepoCond00() && scwin.chkPrtdepoCond03()) {
                let msg = "변경상장사유가 의무보유정보 수정대상이나 수정조치가 이루어지지 않았습니다.\n다시 한번 수정여부를 확인하여 주십시오.\n수정없이 그대로 진행하기를 원하시면 확인을 누르십시오.";
                let res = window.confirm(msg);
                if (!res) {
                    return;
                }
            }
            await scwin.trs(TRS_IDX_INSERT);
        }
    }
};

