/**
 * @method
 * @name isuDtlDtlAdd
 * @description isu Dtl Dtl Add 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isuDtlDtlAdd = async function() {
    if (edt_INDVDL_ISU_RND.getValue() === "") {
        await $c.win.alert("[개별발행회차]를 입력하세요.");
        edt_INDVDL_ISU_RND.focus();
        return;
    }
    if (edt_INDVDL_ISU_DD.getValue() === "") {
        await $c.win.alert("[개별발행일]를 입력하세요.");
        edt_INDVDL_ISU_DD.focus();
        return;
    }
    if (edt_INDVDL_ISU_PRC.getValue() === "") {
        // alert("[개별발행가]를 입력하세요.");edt_INDVDL_ISU_PRC.focus();return;

    }
    if (edt_INDVDL_INCDEC_LIST_SHRS.getValue() === "") {
        await $c.win.alert("[개별증감" + scwin.visuShrsLabelNm + "수]를 입력하세요.");
        edt_INDVDL_INCDEC_LIST_SHRS.focus();
        return;
    }
    let vRow = "";
    if (scwin.vIsuDtlRowPosition !== "") {
        vRow = scwin.vIsuDtlRowPosition;
    } else {
        dts_IsuDtl.insertRow();
        vRow = dts_IsuDtl.getRowCount();
    }

    // alert('[ getObjectValue(edt_INDVDL_ISU_PRC)]'+ getObjectValue(edt_INDVDL_ISU_PRC));
    // alert('[ getObjectValue(edt_INDVDL_INCDEC_LIST_SHRS)]'+ getObjectValue(edt_INDVDL_INCDEC_LIST_SHRS));
    dts_IsuDtl.setCellData(vRow, "ISU_RND", edt_INDVDL_ISU_RND.getValue());
    dts_IsuDtl.setCellData(vRow, "ISU_PRC", edt_INDVDL_ISU_PRC.getValue());
    dts_IsuDtl.setCellData(vRow, "ISU_SHRS", edt_INDVDL_INCDEC_LIST_SHRS.getValue());
    dts_IsuDtl.setCellData(vRow, "ISU_DD", edt_INDVDL_ISU_DD.getValue());
    dts_IsuDtl.setCellData(vRow, "PER1STK_CAP", edt_INDVDL_PER1STK_CAP.getValue());
    dts_IsuDtl.setCellData(vRow, "CORPBND_ISU_RND", edt_CORPBND_ISU_RND.getValue());
    if (dts_IsuDtl.getCellData(vRow, "PER1STK_CAP") > 0) {
        dts_IsuDtl.setCellData(vRow, "NPARVALSTK_YN", "Y");
    }
    await scwin.isuDtlDtlEvent();
};

/**
 * @method
 * @name isuDtlDtlDel
 * @description isu Dtl Dtl Del 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isuDtlDtlDel = async function() {
    if (dts_IsuDtl.getRowCount() === 0) {
        await $c.win.alert("목록에서 [대상]을 선택하세요.");
        return;
    }
    dts_IsuDtl.removeRow(dts_IsuDtl.getRowPosition());
