/**
 * @method
 * @name isuDtlDtlEvent
 * @description isu Dtl Dtl Event 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isuDtlDtlEvent = async function() {
    edt_INDVDL_ISU_RND.setValue('');
    edt_INDVDL_ISU_PRC.setValue('');
    edt_INDVDL_INCDEC_LIST_SHRS.setValue('');
    edt_INDVDL_ISU_DD.setValue('');
    edt_INDVDL_PER1STK_CAP.setValue('');
    edt_CORPBND_ISU_RND.setValue('');
    await scwin.isuPrcCalcuate();
    await scwin.isuShrsCalcuate();
    scwin.vIsuDtlRowPosition = ""; // 초기화

};

/**
 * @method
 * @name isuPrcCalcuate
 * @description isu Prc Calcuate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isuPrcCalcuate = async function() {
    let vIsuPrcSum = 0;
    let vIsuRnd = "";
    let vIsuDd = "";
    try {
        if (dts_IsuDtl.getRowCount() > 0) {
            vIsuPrcSum = parseFloat(dts_IsuDtl.getCellData(1, "ISU_PRC"));
            vIsuRnd = dts_IsuDtl.getCellData(1, "ISU_RND");
            vIsuDd = dts_IsuDtl.getCellData(1, "ISU_DD");
            if (vIsuRnd === "") {
                vIsuRnd = edt_ISU_RND.getValue();
            }
        }
    } catch (err) {
        await $c.win.alert("[개별발행가 계산중  오류]" + err);
    }
    edt_ISU_PRC.setValue(vIsuPrcSum);
    edt_ISU_RND.setValue(vIsuRnd);
    edt_ISU_DD.setValue(vIsuDd);
};

/**
 * @method
 * @name isuShrsCalcuate
 * @description isu Shrs Calcuate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isuShrsCalcuate = async function() {
    let vIsuShrsSum = 0;
    try {
        for (i = 1; i <= dts_IsuDtl.getRowCount(); i++) {
            vIsuShrsSum += parseInt(dts_IsuDtl.getCellData(i, "ISU_SHRS"));
        }
    } catch (err) {
        await $c.win.alert("[개별증감" + scwin.visuShrsLabelNm + "수 합산처리 중  오류]" + err);
    }
    edt_ISU_SHRS.setValue(vIsuShrsSum);
    await scwin.calcuAccIsuShrs();
    await scwin.calcusuCap();
    await scwin.calcuAccIsuCap();
};

/**
 * @method
 * @name calcuAccIsuShrs
 * @description calcu Acc Isu Shrs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcuAccIsuShrs = async function() {
    try {
        let vsum = parseInt(edt_BF_ACC_ISU_SHRS.getValue()) + parseInt(edt_ISU_SHRS.getValue());
        // alert( "[vsum]"+vsum);
        edt_ACC_ISU_SHRS.setValue(vsum);
    } catch (err) {
        await $c.win.alert("[변경후 상장증권수 계산 중 오류]" + err);
    }
};

/**
 * @method
 * @name calcusuCap
 * @description calcusu Cap 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcusuCap = async function() {
    if (scwin.vSecugrpID === SECUGRP_ID_DR) {
        edt_ISU_CAP.setValue('');
    } else {
        try {
            let vRsnCd = cmb_STK_ISU_RSN_CD.getValue();
            let vsum = 0;
            if (vRsnCd === '118' || // 이익소각
                vRsnCd === '160' || // 상호변경
                vRsnCd === '170' || // 액면병합
                vRsnCd === '171' || // 액면분할
                vRsnCd === '177') {
                // 주식소각
                vsum = 0; // 유가

            } else if (vRsnCd === '626' || // 이익소각
                vRsnCd === '643' || // 상호변경
                vRsnCd === '640' || // 액면병합
                vRsnCd === '641' || // 액면분할
                vRsnCd === '650') {
                // 주식소각
                vsum = 0; // 코스닥

            } else {
                if (scwin.vSecugrpID === SECUGRP_ID_MF || scwin.vSecugrpID === SECUGRP_ID_IF) {
                    vsum = parseFloat(edt_ISU_PRC.getValue()) * parseFloat(edt_ISU_SHRS.getValue());
                } else {
                    if (chk_NPARVALSTK_YN.getValue() === "Y") {
                        vsum = parseFloat(edt_PER1STK_CAP.getValue()) * parseFloat(edt_ISU_SHRS.getValue());
                    } else {
                        vsum = parseFloat(edt_PARVAL.getValue()) * parseFloat(edt_ISU_SHRS.getValue());
                    }
                }
            }
            // alert( "[증감자본금 vsum]"+vsum);
            edt_ISU_CAP.setValue(vsum);
        } catch (err) {
            await $c.win.alert("[증감 상장자본금 계산 중  오류]" + err);
        }
    }
};

/**
 * @method
 * @name calcuAccIsuCap
 * @description calcu Acc Isu Cap 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcuAccIsuCap = async function() {
    if (scwin.vSecugrpID === SECUGRP_ID_DR) {
        edt_ACC_ISU_CAP.setValue('');
    } else {
        try {
            let vRsnCd = cmb_STK_ISU_RSN_CD.getValue();
            let vsum = '';
            if (vRsnCd === '118' || // 이익소각
                vRsnCd === '160' || // 상호변경
                vRsnCd === '170' || // 액면병합
                vRsnCd === '177' || // 주식소각
                vRsnCd === '171') {
                // 액면분할
                vsum = edt_BF_ACC_ISU_CAP.getValue(); // 유가
                edt_ISU_CAP.setValue(0); // 유가

            } else if (vRsnCd === '626' || // 이익소각
                vRsnCd === '643' || // 상호변경
                vRsnCd === '640' || // 액면병합
                vRsnCd === '650' || // 주식소각
                vRsnCd === '641') {
                // 액면분할
                vsum = edt_BF_ACC_ISU_CAP.getValue(); // 코스닥
                edt_ISU_CAP.setValue(0); // 코스닥

            } else {
                await scwin.calcusuCap();
                vsum = parseFloat(edt_BF_ACC_ISU_CAP.getValue()) + parseFloat(edt_ISU_CAP.getValue());
            }
            edt_ACC_ISU_CAP.setValue(vsum);
        } catch (err) {
            await $c.win.alert("[변경후 상장자본금 계산 중  오류]" + err);
        }
    }
};

