/**
 * @method
 * @name print12
 * @description 변경상장신청내역  인쇄한다. (totalYn : 통합인쇄 여부 / 배당기산일은 변경전/후를 추가배당일과 동일하게 함-현업요청)
 * @param {*} vBzProcsKey vBzProcsKey
 * @param {String} totalYn totalYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.print12 = async function(vBzProcsKey, totalYn) {

    // dts_Print.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    // 껍데기만 만들고 사용자필드를 사용함
    dts_Print.insertRow();
    await scwin.reportReadSync(vBzProcsKey, DIV_IDX_ISS_REPORT); // return dts_Print
    let userParam = [{
        uid: "ISU_INFO",
        unm: dts_Report.getCellData(1, "COM_NM") + " / " + dts_Report.getCellData(1, "REP_ISU_SRT_CD")
    }, {
        uid: "STK_ISU_RSN_NM",
        unm: dts_Report.getCellData(1, "STK_ISU_RSN_NM")
    }, {
        uid: "BF_CMSTK_SHRS",
        unm: $c.stf.FormatNumberEx(dts_Report.getCellData(1, "BF_CMSTK_SHRS"))
    }, {
        uid: "BF_1PREFSTK_SHRS",
        unm: $c.stf.FormatNumberEx(dts_Report.getCellData(1, "BF_1PREFSTK_SHRS"))
    }, {
        uid: "BF_2PREFSTK_SHRS",
        unm: $c.stf.FormatNumberEx(dts_Report.getCellData(1, "BF_2PREFSTK_SHRS"))
    }, {
        uid: "BF_3PREFSTK_SHRS",
        unm: $c.stf.FormatNumberEx(dts_Report.getCellData(1, "BF_3PREFSTK_SHRS"))
    }, {
        uid: "BF_DIV_RECK_DD",
        unm: $c.stf.FormatDateEx(dts_Report.getCellData(1, "AF_DIV_RECK_DD"))
    }, {
        uid: "BF_PARVAL",
        unm: dts_Report.getCellData(1, "BF_PARVAL")
    }, {
        uid: "BF_ISU_CAP",
        unm: $c.stf.FormatNumberEx(dts_Report.getCellData(1, "BF_ISU_CAP"))
    }, {
        uid: "AF_CMSTK_SHRS",
        unm: $c.stf.FormatNumberEx(dts_Report.getCellData(1, "AF_CMSTK_SHRS"))
    }, {
        uid: "AF_1PREFSTK_SHRS",
        unm: $c.stf.FormatNumberEx(dts_Report.getCellData(1, "AF_1PREFSTK_SHRS"))
    }, {
        uid: "AF_2PREFSTK_SHRS",
        unm: $c.stf.FormatNumberEx(dts_Report.getCellData(1, "AF_2PREFSTK_SHRS"))
    }, {
        uid: "AF_3PREFSTK_SHRS",
        unm: $c.stf.FormatNumberEx(dts_Report.getCellData(1, "AF_3PREFSTK_SHRS"))
    }, {
        uid: "AF_DIV_RECK_DD",
        unm: $c.stf.FormatDateEx(dts_Report.getCellData(1, "AF_DIV_RECK_DD"))
    }, {
        uid: "AF_PARVAL",
        unm: dts_Report.getCellData(1, "AF_PARVAL")
    }, {
        uid: "AF_ISU_CAP",
        unm: $c.stf.FormatNumberEx(dts_Report.getCellData(1, "AF_ISU_CAP"))
    }, {
        uid: "APPROV_DD",
        unm: $c.stf.FormatDateEx(edt_APPROV_DD.getValue())
    }, {
        uid: "ISS_INFO",
        unm: dts_Report.getCellData(1, "ISS_INFO")
    }, {
        uid: "RETISECU_DD",
        unm: $c.stf.FormatDateEx(dts_Report.getCellData(1, "RETISECU_DD"))
    }, {
        uid: "LIST_DD",
        unm: $c.stf.FormatDateEx(dts_Report.getCellData(1, "LIST_DD"))
    }, {
        uid: "CURR_ISO_CD",
        unm: dts_Report.getCellData(1, "CURR_ISO_CD")
    }];

    /* set val, get dts_Report s */
    let gChgCmstkShrs = "";
    let gChg1PrestkShrs = "";
    let gChg2PrestkShrs = "";
    let gChg3PrestkShrs = "";
    let gChgDivDD = "";
    let gChgParVal = "";
    let gChgIsuCap = "";
    let gChgIsuPrc = "";

    // 일단 변경상장을 포함하여 주식발행에서 넣는다.(추가상장인경우 주식발행상세에 데이타 없는경우도 있음)
    gChgCmstkShrs = $c.stf.addCommaMinus(dts_Report.getCellData(1, "CHG_CMSTK_SHRS"));
    gChg1PrestkShrs = $c.stf.addCommaMinus(dts_Report.getCellData(1, "CHG_1PREFSTK_SHRS"));
    gChg2PrestkShrs = $c.stf.addCommaMinus(dts_Report.getCellData(1, "CHG_2PREFSTK_SHRS"));
    gChg3PrestkShrs = $c.stf.addCommaMinus(dts_Report.getCellData(1, "CHG_3PREFSTK_SHRS"));
    gChgIsuCap = $c.stf.addCommaMinus(dts_Report.getCellData(1, "CHG_ISU_CAP"));
    gChgIsuPrc = $c.stf.addCommaMinus(dts_Report.getCellData(1, "CHG_ISU_PRC"));
    gChgDivDD = $c.stf.FormatDateEx(dts_Report.getCellData(1, "CHG_DIV_RECK_DD"));
    gChgParVal = dts_Report.getCellData(1, "CHG_PARVAL");
    /* set val, get dts_Report e */

    // 변경상장 s
    if (cmb_LIST_METHD_TP_CD.getValue() !== LIST_METHD_TP_CD_3) {
        await scwin.reportReadSync(vBzProcsKey, DIV_IDX_ISS_DTL_REPORT); // 주식발행상세

        if (dts_Report.getRowCount() > 0) {
            // 과거자료는 주식발행상세에 정보가 없어서 주식발행에서 넣는다.
            // 초기화..
            gChgCmstkShrs = "";
            gChg1PrestkShrs = "";
            gChg2PrestkShrs = "";
            gChg3PrestkShrs = "";
            gChgDivDD = "";
            gChgParVal = "";
            gChgIsuCap = "";
            gChgIsuPrc = "";
            for (let i = 1; i <= dts_Report.getRowCount(); i++) {
                gChgCmstkShrs += $c.stf.addCommaMinus(dts_Report.getCellData(i, "CHG_CMSTK_SHRS")) + "<br/>";
                gChg1PrestkShrs += $c.stf.addCommaMinus(dts_Report.getCellData(i, "CHG_1PREFSTK_SHRS")) + "<br/>";
                gChg2PrestkShrs += $c.stf.addCommaMinus(dts_Report.getCellData(i, "CHG_2PREFSTK_SHRS")) + "<br/>";
                gChg3PrestkShrs += $c.stf.addCommaMinus(dts_Report.getCellData(i, "CHG_3PREFSTK_SHRS")) + "<br/>";
                gChgIsuCap += $c.stf.addCommaMinus(dts_Report.getCellData(i, "CHG_ISU_CAP")) + "<br/>";
                gChgIsuPrc += $c.stf.addCommaMinus(dts_Report.getCellData(i, "CHG_ISU_PRC")) + "<br/>";
                if (totalYn === 'Y') {
                    gChgDivDD += $c.stf.FormatDateEx(dts_Report.getCellData(1, "CHG_DIV_RECK_DD")) + "<br/>";
                    gChgParVal += dts_Report.getCellData(1, "CHG_PARVAL") + "<br/>";
                }
            }
            if (totalYn === 'N') {
                gChgDivDD = $c.stf.FormatDateEx(dts_Report.getCellData(1, "CHG_DIV_RECK_DD"));
                gChgParVal = dts_Report.getCellData(1, "CHG_PARVAL");
            }
        }
    }
    // 변경상장 e

    // dts_ReportIsuDtl.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_ReportIsuDtl.insertRow();
    dts_ReportIsuDtl.setCellData(1, "CHG_CMSTK_SHRS", $c.ut.defaultStrHtmlSpace(gChgCmstkShrs));
    dts_ReportIsuDtl.setCellData(1, "CHG_1PREFSTK_SHRS", $c.ut.defaultStrHtmlSpace(gChg1PrestkShrs));
    dts_ReportIsuDtl.setCellData(1, "CHG_2PREFSTK_SHRS", $c.ut.defaultStrHtmlSpace(gChg2PrestkShrs));
    dts_ReportIsuDtl.setCellData(1, "CHG_3PREFSTK_SHRS", $c.ut.defaultStrHtmlSpace(gChg3PrestkShrs));
    dts_ReportIsuDtl.setCellData(1, "CHG_DIV_RECK_DD", $c.ut.defaultStrHtmlSpace(gChgDivDD));
    dts_ReportIsuDtl.setCellData(1, "CHG_PARVAL", $c.ut.defaultStrHtmlSpace(gChgParVal));
    dts_ReportIsuDtl.setCellData(1, "CHG_ISU_CAP", $c.ut.defaultStrHtmlSpace(gChgIsuCap));
    dts_ReportIsuDtl.setCellData(1, "CHG_ISU_PRC", $c.ut.defaultStrHtmlSpace(gChgIsuPrc));
    await scwin.reportReadSync(vBzProcsKey, DIV_IDX_PRTDEPO_REPORT);
    // dts_Report2.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    let dataFormatArr = ["PRTDEPO_SHRS:FormatNumberEx"];

    // PDF Convert
    let pdf_rptname = "RLDSTF00007";
    const jsonData1 = $c.rpt.fn_make_dtsToJson1(dts_ReportIsuDtl);
    const jsonData2 = $c.rpt.fn_make_dtsToJson2_wdf(dts_Report2, dts_Report, dataFormatArr);
    userParam.push({
        uid: "jsonData1",
        unm: jsonData1
    });
    userParam.push({
        uid: "jsonData2",
        unm: jsonData2
    });
    $c.rpt.fn_open_report_pdf(pdf_rptname, userParam);
};

