/**
 * @method
 * @name getProvider
 * @description 자식생성창 에서 부모 프레임을 참조.
 * @returns {void}
 * @hidden N
 */
scwin.getProvider = function() {
    let url = frame.srcUrl;
    let arr = url.split("?");
    // alert(url +"     =      "+ arr);
    return (arr.length >= 1 ? $c.frame.path("../" + arr[1]) : undefined);
};

/**
 * @method
 * @name getParentProvider
 * @description get Parent Provider 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParentProvider = function() {
    let url = $c.frame.path("../").srcUrl;
    let arr = url.split("?");
    // alert(url +"     =      "+ arr);
    return (arr.length >= 1 ? $c.frame.path("../../" + arr[1]) : undefined);
};

