/**
 * @method
 * @name setPrestkEndDDEvent
 * @description set Prestk End DDEvent 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setPrestkEndDDEvent = async function() {
    if (chk_INDEFINPD_YN.checked) {
        await $c.win.alert("이미[무기한여부]가 선택되었습니다.\n\n만료일을 입력하시려면 무기한여부선택을 해제하시고 \n존속기한을 선택하십시요.");
        return;
    }
    if (edt_PREFSTK_ISU_DD.getValue() === "") {
        await $c.win.alert("[우선주발행일]을 입력하세요.");
        edt_PREFSTK_ISU_DD.focus();
        return;
    }
    let vTgt;
    let vSrc = edt_PREFSTK_ISU_DD.getValue();
    vTgt = $c.ut.cGetPlusYear(vSrc, edt_PREFSTK_CONTIN_DEADLINE_YYS.getValue());
    edt_PREFSTK_END_DD.setValue(vTgt);
    vSrc = edt_PREFSTK_END_DD.getValue();
    vTgt = $c.ut.cGetPlusMonth(vSrc.substring(0, 4), vSrc.substring(4, 6), vSrc.substring(6, 8), edt_PREFSTK_CONTIN_DEADLINE_MM.getValue());
    edt_PREFSTK_END_DD.setValue(vTgt);
    vSrc = edt_PREFSTK_END_DD.getValue();
    vTgt = $c.ut.cGetPlusDate2(vSrc, edt_PREFSTK_CONTIN_DEADLINE_DYS.getValue());
    edt_PREFSTK_END_DD.setValue(vTgt);
};

/**
 * @method
 * @name setNPARVALSTKYNEvent
 * @description set NPARVALSTKYNEvent 처리
 * @returns {void}
 * @hidden N
 */
scwin.setNPARVALSTKYNEvent = function() {
    if (chk_NPARVALSTK_YN.checked) {
        edt_PARVAL.setReadOnly(true);
        edt_PARVAL.ReadOnlyBackColor = '#b9d4f7';
        edt_PARVAL.setValue('0');
        edt_PER1STK_CAP.setReadOnly(false);
        edt_PER1STK_CAP.ReadOnlyBackColor = '#ffffff';
    } else {
        edt_PARVAL.setReadOnly(false);
        edt_PARVAL.ReadOnlyBackColor = '#ffffff';
        edt_PER1STK_CAP.setReadOnly(true);
        edt_PER1STK_CAP.ReadOnlyBackColor = '#b9d4f7';
        edt_PER1STK_CAP.setValue('');
    }
};

/**
 * @method
 * @name smsSend
 * @description sms Send 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.smsSend = async function() {
    let vMainFormCd;
    let vListMthTpCd = cmb_LIST_METHD_TP_CD.getValue();
    if (vListMthTpCd === LIST_METHD_TP_CD_3) {
        // 변경상장
        if (js_market === "2") {
            vMainFormCd = "70933";
        } else {
            vMainFormCd = "33033";
        }
    } else {
        if (js_market === "2") {
            vMainFormCd = "70932";
        } else {
            vMainFormCd = "33032";
        }
    }
    let url = "/lstproc/ULDSTF05014.gfm?ISUR_CD=" + txb_ISUR_CD.getValue() + "&ACPT_NO=" + scwin.gAcptNoListFee + "&FORM_CD=" + vMainFormCd;
    await $c.frame.CreateDialogFrame("COS_LISTFEE", url, "상장수수료발송", 400, 300, 410, 200, "window");
    await scwin.listFee();
};

