/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    let parentWin = scwin.getProvider();
    // var parentWin = frame.Provider("../");

    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.vSecugrpID = parentWin.fr_SecuGrpId;
    scwin.vPageTYp = parentWin.scwin.vPageTYp;
    scwin.vSPOT_ISU_TRD_MKT_TP_CD = parentWin.scwin.vSPOT_ISU_TRD_MKT_TP_CD;
    txb_ISUR_CD.setValue(parentWin.txb_ISUR_CD.getValue());
    txb_COM_NM.setValue(parentWin.txb_COM_NM.getValue());
    scwin.gAcptNo = parentWin.scwin.gAcptNo;
    scwin.gAcptSeq = (parentWin.scwin.gAcptSeq === "" ? 0 : parentWin.scwin.gAcptSeq);

    // 상장수수료를 위한 접수번호
    scwin.gAcptNoListFee = parentWin.scwin.gAcptNoListFee;
    await scwin.setObjectState();

    // resizeToWin() ;
    await scwin.searchCode();
    await scwin.setComboCode();
    $c.cm.PanelToGroupBox(panel_Item);
    scwin.setPanelPREFSTK(false); // 일단 false;
    scwin.setPREFSTKItem(false); // 일단 false;

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
    buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제

    edt_APPROV_DD.setValue($c.ut.cGetToday("yyyymmdd"));
    if (scwin.vBzProcsNo !== "") {
        cmb_LIST_METHD_TP_CD.CBData = "1^신주상장,2^추가상장,3^변경상장,4^신규상장,5^재상장";
        await scwin.readSync();
    } else {
        if (scwin.gAcptNo !== undefined && scwin.gAcptNo !== "") {
            await scwin.extrReadSync();
            await scwin.setHeader('N');
        } else {
            await scwin.setHeader('Y');
        }
        let vListMthTpCd;
        if (scwin.vPageTYp === '1') {
            // vListMthTpCd =  "1^신주상장,2^추가상장" ;
            vListMthTpCd = "2^추가상장";
            cmb_LIST_METHD_TP_CD.CBData = vListMthTpCd;
            // cmb_LIST_METHD_TP_CD.Index = 1;
            cmb_LIST_METHD_TP_CD.setSelectedIndex(0);
            await scwin.nprefstkReadSync(txb_ISU_CD.getValue());
        } else if (scwin.vPageTYp === '2') {
            vListMthTpCd = "3^변경상장";
            cmb_LIST_METHD_TP_CD.CBData = vListMthTpCd;
            cmb_LIST_METHD_TP_CD.setSelectedIndex(0);
        }
    }
    scwin.setTabPanel();
    buttonSet.setButtonDepCd(dts_ByCorpDepCd, txb_ISUR_CD.getValue(), js_dep_cd);
    if (cmb_STKCERT_KIND_CD.getValue() !== "KDR" && cmb_STKCERT_KIND_CD.getValue().substring(0, 1) === "K") {
        scwin.setNPARVALSTK(true);
    } else {
        scwin.setNPARVALSTK(false);
    }
    // 주식발행사유가 스톡옵션행사(117)(유), 주식매수선택권행사(614)(코) 인경우 주식매수선택권 의무보유 관리 팝업창 호출
    const parentSrc = parentWin.scwin.vScrenID;
    if ((parentSrc === "ULDSTF05200.gfm" || parentSrc === "ULDSTF05255.gfm") && (scwin.vSecugrpID === "ST" || scwin.vSecugrpID === "DR" || scwin.vSecugrpID === "FS") &&
        (cmb_STK_ISU_RSN_CD.getValue() === "117" || cmb_STK_ISU_RSN_CD.getValue() === "614")) {
        scwin.vStkOptIsurCd = txb_ISUR_CD.getValue();
        scwin.vStkOptComNm = txb_COM_NM.getValue();
        const options = {
            id: "ULDSTF40003",
            title: "주식매수선택권 의무보유 관리",
            type: "browserPopup",
            width: "1300px",
            height: "790px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstmgt/ULDSTF40003.gfm", options);
    }
};
